namespace sv_5f55adc9d86d45a98bb8b43ae8743492.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies all subscribed components when the selection changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("wh-1", "Warehouse A – East"),
        new("wh-2", "Warehouse B – West"),
        new("wh-3", "Warehouse C – Central"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public Warehouse CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    /// <summary>
    /// Raised whenever the selected warehouse changes.
    /// Components should call StateHasChanged inside the handler.
    /// </summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_5f55adc9d86d45a98bb8b43ae8743492.Services;

/// <summary>
/// Scoped service that provides low-stock alert data and coordinates
/// notification across all subscribed components in a single circuit.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    private int _lastCount;
    public int LastKnownCount => _lastCount;

    /// <summary>
    /// Raised when new alert data has been fetched. All subscribed
    /// components should re-render when this fires.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component after fetching fresh data.
    /// Stores the count and notifies all subscribers.
    /// </summary>
    public void PublishNewCount(int count)
    {
        _lastCount = count;
        OnAlertDataChanged?.Invoke();
    }
}

