@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" style="width: 220px;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChange;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void HandleStateChange()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChange;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<span class="badge bg-danger rounded-pill">@_count</span>

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertService.LastKnownCount;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private void HandleAlertDataChanged()
    {
        _count = AlertService.LastKnownCount;
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        // Reset to 0 until the next poll brings fresh data for the new warehouse
        _count = 0;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">
    Viewing: <strong>@WarehouseState.CurrentWarehouse.Name</strong>
</p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4 text-danger">@_alertCount</p>
        <p class="text-muted">
            Items below minimum level &bull; refreshes every 10 s
        </p>
    </div>
</div>

@code {
    private int _alertCount;
    private Timer? _pollTimer;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.LastKnownCount;
